use crate::win::psuedocon::PsuedoCon;
use anyhow::Error;
use filedescriptor::FileDescriptor;
use filedescriptor::Pipe;
use portable_pty::cmdbuilder::CommandBuilder;
use portable_pty::Child;
use portable_pty::MasterPty;
use portable_pty::PtyPair;
use portable_pty::PtySize;
use portable_pty::PtySystem;
use portable_pty::SlavePty;
use std::sync::Arc;
use std::sync::Mutex;
use winapi::um::wincon::COORD;

#[derive(Default)]
pub struct ConPtySystem {}

impl PtySystem for ConPtySystem {
    fn openpty(&self, size: PtySize) -> anyhow::Result<PtyPair> {
        let stdin = Pipe::new()?;
        let stdout = Pipe::new()?;

        let con = PsuedoCon::new(
            COORD {
                X: size.cols as i16,
                Y: size.rows as i16,
            },
            stdin.read,
            stdout.write,
        )?;

        let master = ConPtyMasterPty {
            inner: Arc::new(Mutex::new(Inner {
                con: Some(con), // Wrap inside an Option for explicit lifecycle control
                readable: stdout.read,
                writable: Some(stdin.write),
                size,
            })),
        };

        let slave = ConPtySlavePty {
            inner: master.inner.clone(),
        };

        Ok(PtyPair {
            master: Box::new(master),
            slave: Box::new(slave),
        })
    }
}

struct Inner {
    con: Option<PsuedoCon>, // Changed to Option to prevent non-deterministic FFI drops
    readable: FileDescriptor,
    writable: Option<FileDescriptor>,
    size: PtySize,
}

impl Inner {
    pub fn resize(
        &mut self,
        num_rows: u16,
        num_cols: u16,
        pixel_width: u16,
        pixel_height: u16,
    ) -> Result<(), Error> {
        // Perform resize only if the connection is still alive
        if let Some(con) = self.con.as_mut() {
            con.resize(COORD {
                X: num_cols as i16,
                Y: num_rows as i16,
            })?;
        }
        self.size = PtySize {
            rows: num_rows,
            cols: num_cols,
            pixel_width,
            pixel_height,
        };
        Ok(())
    }
}

#[derive(Clone)]
pub struct ConPtyMasterPty {
    inner: Arc<Mutex<Inner>>,
}

pub struct ConPtySlavePty {
    inner: Arc<Mutex<Inner>>,
}

// ADDED: Explicit Drop for MasterPty to deterministically close the PTY
impl Drop for ConPtyMasterPty {
    fn drop(&mut self) {
        if let Ok(mut inner) = self.inner.lock() {
            // Forcibly extract PsuedoCon from the Arc. 
            // This triggers its Drop implementation (and remove_pty_baton in C++) IMMEDIATELY,
            // typically in the main thread, before the FFI environment starts tearing down on exit.
            let _ = inner.con.take();

            // Also release the write pipe
            let _ = inner.writable.take();
        }
    }
}

impl MasterPty for ConPtyMasterPty {
    fn resize(&self, size: PtySize) -> anyhow::Result<()> {
        let mut inner = self.inner.lock().unwrap();
        inner.resize(size.rows, size.cols, size.pixel_width, size.pixel_height)
    }

    fn get_size(&self) -> Result<PtySize, Error> {
        let inner = self.inner.lock().unwrap();
        Ok(inner.size)
    }

    fn try_clone_reader(&self) -> anyhow::Result<Box<dyn std::io::Read + Send>> {
        Ok(Box::new(self.inner.lock().unwrap().readable.try_clone()?))
    }

    fn take_writer(&self) -> anyhow::Result<Box<dyn std::io::Write + Send>> {
        Ok(Box::new(
            self.inner
                .lock()
                .unwrap()
                .writable
                .take()
                .ok_or_else(|| anyhow::anyhow!("writer already taken"))?,
        ))
    }
}

impl SlavePty for ConPtySlavePty {
    fn spawn_command(&self, cmd: CommandBuilder) -> anyhow::Result<Box<dyn Child + Send + Sync>> {
        let inner = self.inner.lock().unwrap();
        // Spawn the command only if the PTY hasn't been closed by the master process
        if let Some(con) = inner.con.as_ref() {
            let child = con.spawn_command(cmd)?;
            Ok(Box::new(child))
        } else {
            Err(anyhow::anyhow!("ConPTY has already been explicitly closed by the master process"))
        }
    }
}
```

### What version of Codex CLI is running?

main (latest commit 4b31848f5)

### What subscription do you have?

API User

### Which model were you using?

_N/A — this is a credential storage issue, not model-specific_

### What platform is your computer?

Darwin 25.1.0 arm64 (also reproducible on Linux)

### What terminal emulator and version are you using (if applicable)?

_N/A_

### What issue are you seeing?

When the system keyring is unavailable (headless servers, containers, or keyring service crashes), `AutoAuthStorage` silently falls back to loading credentials from a plaintext JSON file (`~/.codex/auth.json`) without any user-visible warning.

Additionally, when credentials are successfully saved to the keyring, the code attempts to delete the fallback file but silently swallows the error if deletion fails:

```rust
// codex-rs/core/src/auth/storage.rs lines 201-209
fn save(&self, auth: &AuthDotJson) -> std::io::Result<()> {
    let key = compute_store_key(&self.codex_home)?;
    let serialized = serde_json::to_string(auth).map_err(std::io::Error::other)?;
    self.save_to_keyring(&key, &serialized)?;
    if let Err(err) = delete_file_if_exists(&self.codex_home) {
        warn!("failed to remove CLI auth fallback file: {err}");
    }
    Ok(())
}
```

The fallback loading path (`storage.rs` lines 241-250) also logs only a `warn!` on keyring failure before falling back:

```rust
fn load(&self) -> std::io::Result<Option<AuthDotJson>> {
    match self.keyring_storage.load() {
        Ok(Some(auth)) => Ok(Some(auth)),
        Ok(None) => self.file_storage.load(),
        Err(err) => {
            warn!("failed to load CLI auth from keyring, falling back to file storage: {err}");
            self.file_storage.load()
        }
    }
}
```

There's also a file permission concern in `storage.rs` lines 118-124 — `OpenOptions::mode(0o600)` only applies when the file is **created**, not when an existing file is opened with `truncate`. If the file already exists with wider permissions (e.g. `0o644`), the credentials get written to a world-readable file.

### What steps can reproduce the bug?

1. Log in to Codex CLI normally (credentials saved to keyring + fallback file)
2. Stop the keyring service (e.g., `systemctl --user stop gnome-keyring` on Linux, or just run in a container/SSH session without keyring)
3. Start Codex CLI — it loads credentials from the plaintext file silently, only a `warn!` log is emitted
4. Even after keyring is restored and credentials are re-saved to keyring, the plaintext file may remain on disk if `delete_file_if_exists` fails

### What is the expected behavior?

- When falling back to file storage, the user should see a clear visible warning (not just a log entry) explaining that credentials are being loaded from disk
- If the fallback file cannot be deleted after keyring save, the error should be surfaced to the user rather than silently swallowed
- File permissions should be explicitly set (via `fchmod` or equivalent) on every write, not just on file creation
- Ideally, the CLI should refuse to use file-based credentials in security-sensitive operations, or at least require explicit user opt-in for file storage

### Additional information

The combination of silent fallback + stale credentials on disk creates an unnecessary attack surface. An attacker with local file write access could replace the credentials file while the keyring is unavailable, and the CLI would load the tampered credentials without question. This is a defense-in-depth concern rather than a direct exploit, but worth addressing given that the keyring exists specifically to avoid storing secrets on disk.
